    if (pr) {
        logFoundPr(pr);
        return { pr: pr };
    }
    console.warn('No open PR found for ticket:', ctx.ticketKey);
    return { failed: true, comment: ctx.noTicket ? null : buildNoPrComment(ctx.ticketKey) };
