    jiraComment += 'AI Code Reviewer is analyzing the pull request for:\n' +
        '* 🔒 Security vulnerabilities\n' +
        '* 🏗️ Code quality & OOP principles\n' +
        '* ✅ Task alignment with requirements\n' +
        '* 🧪 Testing adequacy\n\n' +
