// ── gh-1332: the finding-identity registry injection ─────────────────────────

function machineAuthorLoginsOf(ctx) {
    return machineAuthorModule.machineAuthorLogins(
        machineAuthorModule.resolveMachineAuthor(ctx.jp, ctx.config));
